const upcomingEventsNearDonor = `-- name: UpcomingEventsNearDonor :many
SELECT id, slug, title, type, description, venue, address, city, zip, starts_at, ends_at, capacity, publish_state, published_at, created_at, updated_at, qualifying_perk, cancelled_at, booking_opens_at, time_zone FROM donor_events
WHERE publish_state='PUBLISHED'
  AND cancelled_at IS NULL
  AND type <> 'INVITE_ONLY'
  AND starts_at > $1::timestamptz
  AND (
    ($2::text <> '' AND lower(city) = lower($2::text))
    OR ($3::text <> '' AND left(zip, 3) = $3::text)
  )
ORDER BY starts_at ASC, id
LIMIT 100
`

type UpcomingEventsNearDonorParams struct {
	Now  pgtype.Timestamptz `json:"now"`
	City string             `json:"city"`
	Zip3 string             `json:"zip3"`
}

// E-2: published events in and near the donor's city (same city label OR same
// three-digit ZIP region), upcoming only, soonest first. The near-city match
// is empty-safe: a donor with no city/zip matches nothing on that predicate.
// INVITE_ONLY events are excluded here; they surface only through the 4.4
// gated path (qualifying badge or admin guest list), never the open list.
func (q *Queries) UpcomingEventsNearDonor(ctx context.Context, arg UpcomingEventsNearDonorParams) ([]DonorEvent, error) {
	rows, err := q.db.Query(ctx, upcomingEventsNearDonor, arg.Now, arg.City, arg.Zip3)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DonorEvent{}
	for rows.Next() {
		var i DonorEvent
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Title,
			&i.Type,
			&i.Description,
			&i.Venue,
			&i.Address,
			&i.City,
			&i.Zip,
			&i.StartsAt,
			&i.EndsAt,
			&i.Capacity,
			&i.PublishState,
			&i.PublishedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.QualifyingPerk,
			&i.CancelledAt,
			&i.BookingOpensAt,
			&i.TimeZone,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

